{"execution_provenance":"caller_reported_not_executed_by_pilot","packet":{"baseline":{"actor":"codex-v023-20261004-composite-annotations","choice":"supports"},"execution":{"command":["cargo","test","--release","--features","self-host","--test","selfhost_composite_annotations","--test","selfhost_composite_projections","--test","selfhost_composite_members","--test","selfhost_structural_types","--test","selfhost_enum_types","--test","selfhost_composite_types","--test","selfhost_type_transport","--test","selfhost_artifact_identity","--test","selfhost_monomorphize_identity","--test","selfhost_parse","--test","selfhost_typecheck","--test","self_hosted_backend"],"executed_tests":242,"exit_code":0,"feature_set":["self-host"]},"id":"v023-20261004-composite-annotations-execution","input":{"claim":"All seven selected composite annotation controls have identical complete artifacts and both compiler outputs execute to the integer seven.","evidence":"fn composite_annotations_preserve_artifacts_and_execution() {
    for source in [
        "fn main() -> Word { let x: () = (); 7 }",
        "fn main() -> Word { let x: [Word; 2] = [7, 2]; x[0] }",
        "fn main() -> Word { let x: [[Word; 2]; 2] = [[7, 2], [3, 4]]; x[0][0] }",
        "fn main() -> Word { let x: (Word, Word) = (7, 2); x.0 }",
        "fn main() -> Word { let x: [(Word, Word); 2] = [(7, 2), (3, 4)]; x[0].0 }",
        "struct P { x: Word } fn main() -> Word { let x: [P; 1] = [P { x: 7 }]; x[0].x }",
        "fn main() -> Word { let x: [Word; 2] = [7, 2]; let y = if true { let x: (Word, Word) = (1, 2); x.0 } else { let x: Word = 2; x }; x[0] }",
    ] {
        let ast = keleusma::parser::parse(&keleusma::lexer::tokenize(source).unwrap()).unwrap();
        let reference = keleusma::compiler::compile(&ast).unwrap();
        let actual =
            keleusma::selfhost::self_hosted_compile(source, &keleusma::target::Target::host())
                .unwrap_or_else(|error| panic!("{source}: {error:?}"));
        assert_eq!(
            actual.to_bytes().unwrap(),
            reference.to_bytes().unwrap(),
            "{source}"
        );
        for module in [reference, actual] {
            let persistent = keleusma::vm::required_persistent_capacity_for(&module);
            let mut arena =
                keleusma::Arena::with_capacity(keleusma::vm::DEFAULT_ARENA_CAPACITY + persistent);
            arena.resize_persistent(persistent).unwrap();
            let entry = module
                .chunks
                .iter()
                .position(|chunk| chunk.name == "main")
                .unwrap();
            let mut vm = keleusma::vm::Vm::new(module, &arena).unwrap();
            assert!(
                matches!(
                    vm.call_function(entry, &[]).unwrap(),
                    keleusma::vm::VmState::Finished(keleusma::bytecode::Value::Int(7))
                ),
                "{source}"
            );
        }
    }
}

