{"execution_provenance":"caller_reported_not_executed_by_pilot","packet":{"baseline":{"actor":"codex-v023-20261004-composite-annotations","choice":"supports"},"execution":{"command":["cargo","test","--release","--features","self-host","--test","selfhost_composite_annotations","--test","selfhost_composite_projections","--test","selfhost_composite_members","--test","selfhost_structural_types","--test","selfhost_enum_types","--test","selfhost_composite_types","--test","selfhost_type_transport","--test","selfhost_artifact_identity","--test","selfhost_monomorphize_identity","--test","selfhost_parse","--test","selfhost_typecheck","--test","self_hosted_backend"],"executed_tests":242,"exit_code":0,"feature_set":["self-host"]},"id":"v023-20261004-composite-annotations-unit-tail","input":{"claim":"The written unit tail retains its return requirement and independently rejects a function declared to return Word.","evidence":"fn a_written_unit_expression_remains_a_real_tail() {
    const SRC: &str = "fn s() -> Word { () }";
    let ast = parse(&tokenize(SRC).expect("lex")).expect("parse");
    assert!(keleusma::compiler::compile(&ast).is_err());
    let (rows, _) = keleusma::selfhost::expression_rows_from_pipeline(SRC);
    let tails: Vec<_> = rows.iter().filter(|(kind, _, _)| *kind == 8).collect();
    assert_eq!(
        tails.len(),
        1,
        "written unit cannot disappear as a missing tail"
    );
    assert_eq!((tails[0].1.0, tails[0].2.0), (6, 1));
    assert!(!keleusma::selfhost::type_check_source_via_kel(SRC).unwrap());
    assert!(matches!(
        keleusma::selfhost::self_hosted_compile(SRC, &keleusma::target::Target::host()),
        Err(keleusma::selfhost::SelfHostError::PipelineRejected { .. })
    ));
    let (_, records) = keleusma::selfhost::parse_record_trace(SRC);
    assert_eq!(
        records
            .iter()
            .filter(|(kind, arg, _)| *kind == 20 && *arg == 3)
            .count(),
        1
    );
}

