#![cfg(feature = "self-host")]

use keleusma::selfhost::wire_auxiliary_directory_via_kel;
use keleusma_wire::{WireBuilder, WireView};

fn assert_directory(bytes: &[u8]) {
    let actual = wire_auxiliary_directory_via_kel(bytes).unwrap();
