            for byte in 0..144 {
                for bit in 0..8 {
                    let mut damaged = clean.clone();
                    damaged[byte] ^= 1 << bit;
                    assert!(compare(vm, shared, &damaged), "byte {byte}, bit {bit}");
                    accepted += 1;
                }
            }
