            "const data d { values: [Word; 3] = [4, 5, 6] } fn main() -> Word { d.values[1] }",
            5,
        ),
        (
            "const data d { value: ((Word, Word), Word) = ((1, 2), 3) } fn main() -> Word { (d.value.0).0 + d.value.1 }",
