        "(Word, ((Word, P), Word))",
    ] {
        let source = format!(
            "struct P {{ x: Word, y: Word }} fn main(a: {shape}, b: {shape}) -> bool {{ a == b }}"
        );
        let reference = keleusma::selfhost::compile_src(&source);
        let actual =
            keleusma::selfhost::self_hosted_compile(&source, &keleusma::target::Target::host())
